```python
"""A parser for standard 5-field cron expressions.

Public API:
    parse_cron("0 12 * * 1-5") -> CronSchedule
    CronSchedule.describe()    -> "At 12:00 on Monday through Friday"

The module reads top-down:
    1. Errors and value objects  (CronError, FieldSpec, CronField, CronSchedule)
    2. Field definitions         (the five columns and their legal ranges)
    3. Parsing                   (expression -> columns -> terms -> values)
    4. Describing                (fields -> English)
    5. Small formatting helpers
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import List, Optional, Sequence, Set, Tuple

__all__ = ["CronError", "FieldSpec", "CronField", "CronSchedule", "parse_cron"]


# ---------------------------------------------------------------------------
# Errors
# ---------------------------------------------------------------------------


class CronError(ValueError):
    """Raised when a cron expression is malformed or a value is out of range."""


# ---------------------------------------------------------------------------
# Value objects
# ---------------------------------------------------------------------------


@dataclass(frozen=True)
class FieldSpec:
    """Static description of one cron column: its name and legal bounds."""

    name: str
    min_value: int
    max_value: int

    @property
    def full_range(self) -> range:
        return range(self.min_value, self.max_value + 1)

    def validate(self, value: int) -> None:
        if value not in self.full_range:
            raise CronError(
                f"{self.name} value {value} is out of range "
                f"({self.min_value}-{self.max_value})"
            )


@dataclass(frozen=True)
class CronField:
    """One parsed column: the raw text plus every concrete value it matches."""

    spec: FieldSpec
    raw: str
    values: Tuple[int, ...]

    @property
    def is_wildcard(self) -> bool:
        """True when the field matches every legal value (`*`, or `0-59`, ...)."""
        return len(self.values) == len(self.spec.full_range)

    @property
    def step(self) -> Optional[int]:
        """The stride if the values are evenly spaced by more than 1, else None.

        `*/15` over 0-59 yields (0, 15, 30, 45) -> 15.
        `1,2,3` yields None: a spacing of 1 is not a meaningful "every N".
        """
        if len(self.values) < 2:
            return None
        gaps = {later - earlier for earlier, later in zip(self.values, self.values[1:])}
        if len(gaps) != 1:
            return None
        gap = gaps.pop()
        return gap if gap > 1 else None

    @property
    def spans_full_range(self) -> bool:
        """True when the values start at the minimum and run to the end.

        This distinguishes `*/2` (every 2 hours, all day long) from `0-6/2`
        (every 2 hours, but only in the morning).
        """
        if not self.values:
            return False
        stride = self.step or 1
        starts_at_minimum = self.values[0] == self.spec.min_value
        reaches_the_end = self.values[-1] + stride > self.spec.max_value
        return starts_at_minimum and reaches_the_end


@dataclass(frozen=True)
class CronSchedule:
    """A fully parsed cron expression."""

    expression: str
    minute: CronField
    hour: CronField
    day_of_month: CronField
    month: CronField
    day_of_week: CronField

    @property
    def fields(self) -> Tuple[CronField, ...]:
        return (self.minute, self.hour, self.day_of_month, self.month, self.day_of_week)

    def matches(
        self, minute: int, hour: int, day: int, month: int, weekday: int
    ) -> bool:
        """True if the given time components satisfy every field of the schedule."""
        return (
            minute in self.minute.values
            and hour in self.hour.values
            and day in self.day_of_month.values
            and month in self.month.values
            and weekday in self.day_of_week.values
        )

    def describe(self) -> str:
        """Return a human-readable English description of this schedule."""
        return describe_schedule(self)


# ---------------------------------------------------------------------------
# Field definitions
# ---------------------------------------------------------------------------

MINUTE = FieldSpec("minute", 0, 59)
HOUR = FieldSpec("hour", 0, 23)
DAY_OF_MONTH = FieldSpec("day of month", 1, 31)
MONTH = FieldSpec("month", 1, 12)
DAY_OF_WEEK = FieldSpec("day of week", 0, 6)

FIELD_SPECS: Tuple[FieldSpec, ...] = (MINUTE, HOUR, DAY_OF_MONTH, MONTH, DAY_OF_WEEK)

WEEKDAY_NAMES: Tuple[str, ...] = (
    "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday",
)

MONTH_NAMES: Tuple[str, ...] = (
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December",
)


# ---------------------------------------------------------------------------
# Parsing
# ---------------------------------------------------------------------------


def parse_cron(expression: str) -> CronSchedule:
    """Parse a 5-field cron expression into a CronSchedule.

    Raises CronError if the expression is malformed or any value is out of range.
    """
    columns = split_into_columns(expression)
    fields = tuple(
        parse_field(column, spec) for column, spec in zip(columns, FIELD_SPECS)
    )
    return CronSchedule(expression.strip(), *fields)


def split_into_columns(expression: str) -> Tuple[str, ...]:
    """Split an expression on whitespace and require exactly five columns."""
    if not isinstance(expression, str):
        raise CronError(f"Expected a string expression, got {type(expression).__name__}")

    columns = tuple(expression.split())
    if not columns:
        raise CronError("Cron expression is empty")
    if len(columns) != len(FIELD_SPECS):
        expected = " ".join(spec.name.replace(" ", "_") for spec in FIELD_SPECS)
        raise CronError(
            f"Expected 5 fields ({expected}), got {len(columns)}: {expression!r}"
        )
    return columns


def parse_field(column: str, spec: FieldSpec) -> CronField:
    """Parse one column (`*`, `1-30/5`, `1,3,5`, ...) against its field spec.

    A column is a comma-separated list of terms; the field matches the union of
    all its terms' values.
    """
    terms = column.split(",")
    if any(term == "" for term in terms):
        raise CronError(f"Empty term in {spec.name} field: {column!r}")

    matched: Set[int] = set()
    for term in terms:
        matched.update(parse_term(term, spec))
    return CronField(spec=spec, raw=column, values=tuple(sorted(matched)))


def parse_term(term: str, spec: FieldSpec) -> Sequence[int]:
    """Parse a single term: `*`, `5`, `1-5`, `*/15`, `1-30/5`, or `5/10`."""
    base, step = split_step(term, spec)
    return apply_step(parse_base(base, spec), base, step, spec)


def split_step(term: str, spec: FieldSpec) -> Tuple[str, int]:
    """Split `base/step` into its two parts, defaulting the step to 1."""
    if "/" not in term:
        return term, 1

    base, _, step_text = term.partition("/")
    if base == "":
        raise CronError(f"Missing value before '/' in {spec.name} field: {term!r}")

    step = parse_integer(step_text, f"step in {spec.name} field {term!r}")
    if step < 1:
        raise CronError(f"Step must be at least 1 in {spec.name} field: {term!r}")
    return base, step


def parse_base(base: str, spec: FieldSpec) -> Sequence[int]:
    """Expand the non-step part of a term into every value it covers."""
    if base == "*":
        return list(spec.full_range)
    if "-" in base:
        return parse_range(base, spec)
    return [parse_single_value(base, spec)]


def parse_range(base: str, spec: FieldSpec) -> Sequence[int]:
    """Expand `start-end` into an inclusive list of values."""
    start_text, _, end_text = base.partition("-")
    start = parse_single_value(start_text, spec)
    end = parse_single_value(end_text, spec)
    if start > end:
        raise CronError(
            f"Range start {start} is greater than end {end} in {spec.name} field"
        )
    return list(range(start, end + 1))


def parse_single_value(text: str, spec: FieldSpec) -> int:
    """Parse one literal number and check it against the field's bounds."""
    value = parse_integer(text, f"{spec.name} value")
    spec.validate(value)
    return value


def parse_integer(text: str, context: str) -> int:
    """Parse a bare non-negative integer, rejecting signs and stray characters."""
    if not text.isdigit():
        raise CronError(f"Invalid {context}: {text!r} is not a non-negative integer")
    return int(text)


def apply_step(
    values: Sequence[int], base: str, step: int, spec: FieldSpec
) -> Sequence[int]:
    """Keep every `step`-th value of an expanded base.

    A bare start value combined with a step (`5/10`) is read as "from 5 to the
    field maximum", matching Vixie cron: in the minute field it means
    5, 15, 25, 35, 45, 55.
    """
    is_open_ended_start = step > 1 and base != "*" and len(values) == 1
    if is_open_ended_start:
        values = list(range(values[0], spec.max_value + 1))
    return values[::step]


# ---------------------------------------------------------------------------
# Describing
# ---------------------------------------------------------------------------


def describe_schedule(schedule: CronSchedule) -> str:
    """Render a schedule as an English sentence.

    The sentence is assembled from independent clauses:
        <time clause> [on <day clause>] [in <month clause>]
    """
    clauses = [describe_time(schedule.minute, schedule.hour)]
    clauses.extend(describe_days(schedule.day_of_month, schedule.day_of_week))
    clauses.extend(describe_months(schedule.month))
    return " ".join(clauses)


def describe_time(minute: CronField, hour: CronField) -> str:
    """Describe the minute/hour pair -- the trickiest part of the sentence.

    The cases are ordered from the broadest schedule to the most specific.
    """
    if minute.is_wildcard and hour.is_wildcard:
        return "Every minute"

    if is_periodic(minute):
        return join_clause(f"Every {minute.step} minutes", describe_hour_window(hour))

    if minute.is_wildcard:
        return join_clause("Every minute", describe_hour_window(hour))

    # From here on the minute field is an explicit set of values.
    if is_periodic(hour):
        return f"Every {hour.step} hours, {describe_minute_offset(minute)}"

    if hour.is_wildcard:
        return f"Every hour, {describe_minute_offset(minute)}"

    return describe_explicit_times(minute, hour)


def describe_hour_window(hour: CronField) -> str:
    """Describe which hours are in play, or "" when every hour qualifies."""
    if hour.is_wildcard:
        return ""
    if is_periodic(hour):
        return f"past every {ordinal(hour.step or 1)} hour"
    return f"during {describe_number_runs(hour, 'hour', 'hours')}"


def describe_minute_offset(minute: CronField) -> str:
    """Describe minutes within an hour: "on the hour" or "at minute 30"."""
    if minute.values == (0,):
        return "on the hour"
    return f"at {describe_number_runs(minute, 'minute', 'minutes')}"


MAX_ENUMERATED_TIMES = 6


def describe_explicit_times(minute: CronField, hour: CronField) -> str:
    """Describe fixed hour/minute combinations as clock times.

    Short combinations are spelled out ("At 08:30"); longer ones would produce
    an unreadable list, so they fall back to a summary phrase.
    """
    times = [format_clock(h, m) for h in hour.values for m in minute.values]
    if len(times) <= MAX_ENUMERATED_TIMES:
        return f"At {join_phrases(times)}"

    minutes = describe_number_runs(minute, "minute", "minutes")
    hours = describe_number_runs(hour, "hour", "hours")
    return f"At {minutes} past {hours}"


def describe_days(day_of_month: CronField, day_of_week: CronField) -> List[str]:
    """Describe the day constraints, if any, as `on ...` clauses."""
    clauses: List[str] = []
    if not day_of_month.is_wildcard:
        clauses.append(f"on {describe_month_days(day_of_month)}")
    if not day_of_week.is_wildcard:
        clauses.append(f"on {describe_weekdays(day_of_week)}")
    return clauses


def describe_month_days(field: CronField) -> str:
    """Describe day-of-month values, e.g. "the 1st of every month"."""
    if is_periodic(field):
        return f"every {ordinal(field.step or 1)} day of the month"
    days = join_phrases([f"the {ordinal(value)}" for value in field.values])
    return f"{days} of every month"


def describe_weekdays(field: CronField) -> str:
    """Describe weekday values, e.g. "Monday through Friday"."""
    return describe_named_values(field, WEEKDAY_NAMES, first_value=0)


def describe_months(field: CronField) -> List[str]:
    """Describe the month constraint, if any, as an `in ...` clause."""
    if field.is_wildcard:
        return []
    return [f"in {describe_named_values(field, MONTH_NAMES, first_value=1)}"]


def describe_named_values(
    field: CronField, names: Sequence[str], first_value: int
) -> str:
    """Render values as names, collapsing consecutive runs into "A through B"."""
    phrases = [
        name_run(run, names, first_value) for run in group_consecutive(field.values)
    ]
    return join_phrases(phrases)


def name_run(run: Sequence[int], names: Sequence[str], first_value: int) -> str:
    """Render one consecutive run of named values."""
    first, last = names[run[0] - first_value], names[run[-1] - first_value]
    if len(run) == 1:
        return first
    if len(run) == 2:
        return f"{first} and {last}"
    return f"{first} through {last}"


def describe_number_runs(field: CronField, singular: str, plural: str) -> str:
    """Render numeric values with a label, e.g. "minutes 1 through 30 and 45"."""
    label = singular if is_single(field) else plural
    runs = [number_run(run) for run in group_consecutive(field.values)]
    return f"{label} {join_phrases(runs)}"


def number_run(run: Sequence[int]) -> str:
    """Render one consecutive run of numbers."""
    if len(run) == 1:
        return str(run[0])
    return f"{run[0]} through {run[-1]}"


# ---------------------------------------------------------------------------
# Small formatting helpers
# ---------------------------------------------------------------------------


def is_single(field: CronField) -> bool:
    """True when the field matches exactly one value."""
    return len(field.values) == 1


def is_periodic(field: CronField) -> bool:
    """True when the field reads naturally as "every N", e.g. `*/15` or `*/2`."""
    return field.step is not None and field.spans_full_range


def format_clock(hour: int, minute: int) -> str:
    """Format an hour/minute pair as 24-hour clock text, e.g. "08:30"."""
    if hour == 0 and minute == 0:
        return "midnight"
    return f"{hour:02d}:{minute:02d}"


def group_consecutive(values: Sequence[int]) -> List[List[int]]:
    """Split a sorted sequence into runs of consecutive integers.

    [1, 2, 3, 5] -> [[1, 2, 3], [5]]
    """
    runs: List[List[int]] = []
    for value in values:
        if runs and value == runs[-1][-1] + 1:
            runs[-1].append(value)
        else:
            runs.append([value])
    return runs


def join_phrases(phrases: Sequence[str]) -> str:
    """Join phrases with commas and a serial "and": "A", "A and B", "A, B, and C"."""
    if not phrases:
        return ""
    if len(phrases) == 1:
        return phrases[0]
    if len(phrases) == 2:
        return f"{phrases[0]} and {phrases[1]}"
    return ", ".join(phrases[:-1]) + f", and {phrases[-1]}"


def join_clause(head: str, tail: str) -> str:
    """Append an optional trailing clause, skipping it when it is empty."""
    return f"{head} {tail}" if tail else head


def ordinal(value: int) -> str:
    """Return the English ordinal for a number: 1 -> "1st", 22 -> "22nd"."""
    if 10 <= value % 100 <= 20:
        suffix = "th"
    else:
        suffix = {1: "st", 2: "nd", 3: "rd"}.get(value % 10, "th")
    return f"{value}{suffix}"
