```python
"""
A parser for standard 5-field cron expressions.

    minute hour day_of_month month day_of_week

Usage:
    schedule = parse_cron_expression("0 12 * * 1-5")
    schedule.describe()   -> "At 12:00 on Monday through Friday"

The file is organized top-down:
  1. Constants and the CronParseError exception.
  2. The CronField/CronSchedule data model.
  3. parse_cron_expression(): the public entry point, and the field-level
     parsing helpers it relies on.
  4. describe(): the public description entry point, and the helpers it
     relies on, roughly from "whole schedule" down to "single number".
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Dict, List, Optional, Tuple

# --------------------------------------------------------------------------
# Constants
# --------------------------------------------------------------------------

# Inclusive (minimum, maximum) allowed values for each of the five fields.
FIELD_BOUNDS: Dict[str, Tuple[int, int]] = {
    "minute": (0, 59),
    "hour": (0, 23),
    "day_of_month": (1, 31),
    "month": (1, 12),
    "day_of_week": (0, 6),  # 0 = Sunday
}

# The order the five fields appear in a cron expression.
FIELD_ORDER: Tuple[str, ...] = (
    "minute",
    "hour",
    "day_of_month",
    "month",
    "day_of_week",
)

DAY_NAMES: Tuple[str, ...] = (
    "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday",
)

# Indexed 1-12 to match cron's 1-based months; index 0 is unused.
MONTH_NAMES: Tuple[str, ...] = (
    "", "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December",
)


class CronParseError(ValueError):
    """Raised when a cron expression or one of its fields is invalid."""


# --------------------------------------------------------------------------
# Data model
# --------------------------------------------------------------------------

@dataclass(frozen=True)
class CronField:
    """One parsed field of a cron expression, e.g. the hour field "*/2"."""

    name: str           # "minute", "hour", "day_of_month", "month", or "day_of_week"
    raw: str             # the original text, e.g. "*/2"
    values: List[int]    # every concrete value this field matches, sorted ascending


@dataclass(frozen=True)
class CronSchedule:
    """A fully parsed 5-field cron expression."""

    minute: CronField
    hour: CronField
    day_of_month: CronField
    month: CronField
    day_of_week: CronField

    def describe(self) -> str:
        """Render this schedule as a human-readable English sentence."""
        time_phrase = describe_time(self.minute, self.hour)
        date_phrase = describe_date(self.day_of_month, self.month, self.day_of_week)
        if date_phrase is None:
            return time_phrase
        return f"{time_phrase} {date_phrase}"


# --------------------------------------------------------------------------
# Parsing: public entry point
# --------------------------------------------------------------------------

def parse_cron_expression(expression: str) -> CronSchedule:
    """Parse a 5-field cron expression into a CronSchedule.

    Raises CronParseError if the expression does not have exactly five
    whitespace-separated fields, or if any field is malformed.
    """
    fields = expression.split()
    if len(fields) != 5:
        raise CronParseError(
            f"Expected 5 space-separated fields, got {len(fields)}: '{expression}'"
        )

    parsed = {
        name: parse_field(name, raw_field)
        for name, raw_field in zip(FIELD_ORDER, fields)
    }
    return CronSchedule(**parsed)


# --------------------------------------------------------------------------
# Parsing: single-field helpers
# --------------------------------------------------------------------------

def parse_field(field_name: str, expression: str) -> CronField:
    """Parse one comma-separated cron field, e.g. "1,15-20,*/10"."""
    minimum, maximum = FIELD_BOUNDS[field_name]

    values = set()
    for segment in expression.split(","):
        values.update(parse_field_segment(field_name, segment, minimum, maximum))

    if not values:
        raise CronParseError(f"Field '{field_name}' has no values: '{expression}'")

    return CronField(name=field_name, raw=expression, values=sorted(values))


def parse_field_segment(
    field_name: str, segment: str, minimum: int, maximum: int
) -> List[int]:
    """Parse a single comma-separated piece of a field, e.g. "1-30/5" or "*"."""
    segment = segment.strip()
    if not segment:
        raise CronParseError(f"Field '{field_name}' has an empty value: '{segment}'")

    range_part, _, step_part = segment.partition("/")
    step = parse_step(field_name, step_part) if step_part else 1
    start, end = parse_range(field_name, range_part, minimum, maximum)

    ensure_within_bounds(field_name, start, minimum, maximum)
    ensure_within_bounds(field_name, end, minimum, maximum)
    if start > end:
        raise CronParseError(
            f"Field '{field_name}' has a backwards range: '{range_part}'"
        )

    return list(range(start, end + 1, step))


def parse_range(
    field_name: str, range_part: str, minimum: int, maximum: int
) -> Tuple[int, int]:
    """Parse the non-step portion of a segment: "*", "N", or "N-M"."""
    if range_part == "*":
        return minimum, maximum
    if "-" in range_part:
        start_text, _, end_text = range_part.partition("-")
        return parse_int(field_name, start_text), parse_int(field_name, end_text)
    value = parse_int(field_name, range_part)
    return value, value


def parse_step(field_name: str, step_part: str) -> int:
    """Parse the "/N" step suffix of a segment."""
    step = parse_int(field_name, step_part)
    if step <= 0:
        raise CronParseError(
            f"Field '{field_name}' has a non-positive step: '/{step_part}'"
        )
    return step


def parse_int(field_name: str, text: str) -> int:
    """Parse a plain non-negative integer, with a clear error on failure."""
    if not text.isdigit():
        raise CronParseError(f"Field '{field_name}' has an invalid number: '{text}'")
    return int(text)


def ensure_within_bounds(field_name: str, value: int, minimum: int, maximum: int) -> None:
    if not minimum <= value <= maximum:
        raise CronParseError(
            f"Field '{field_name}' value {value} is outside the valid range "
            f"{minimum}-{maximum}"
        )


# --------------------------------------------------------------------------
# Description: whole-schedule helpers
# --------------------------------------------------------------------------

def describe_time(minute: CronField, hour: CronField) -> str:
    """Describe the minute/hour portion of the schedule, e.g. "At 12:00"."""
    if is_wildcard(minute) and is_wildcard(hour):
        return "Every minute"

    minute_step = wildcard_step(minute)
    if minute_step is not None and is_wildcard(hour):
        return f"Every {minute_step} minutes"

    hour_step = wildcard_step(hour)
    minute_value = single_value(minute)
    hour_value = single_value(hour)

    if minute_value == 0 and hour_step is not None:
        return f"Every {hour_step} hours, on the hour"
    if minute_value == 0 and hour_value == 0:
        return "At midnight"
    if minute_value is not None and hour_value is not None:
        return f"At {hour_value:02d}:{minute_value:02d}"

    # Fallback for combinations too irregular for a fixed phrase, e.g.
    # minute="0,30" hour="9-17".
    return (
        f"At minute {describe_number_list(minute.values)} "
        f"past hour {describe_number_list(hour.values)}"
    )


def describe_date(
    day_of_month: CronField, month: CronField, day_of_week: CronField
) -> Optional[str]:
    """Describe the day-of-month/month/day-of-week portion of the schedule.

    Returns None when all three fields are wildcards, since then the time
    phrase alone (e.g. "Every minute") already says everything.
    """
    dom_restricted = not is_wildcard(day_of_month)
    month_restricted = not is_wildcard(month)
    dow_restricted = not is_wildcard(day_of_week)

    if not (dom_restricted or month_restricted or dow_restricted):
        return None

    # Common single-field cases get their own natural phrasing.
    if dom_restricted and not month_restricted and not dow_restricted:
        return f"on the {describe_day_of_month(day_of_month)} of every month"
    if dow_restricted and not dom_restricted and not month_restricted:
        return f"on {describe_day_of_week(day_of_week)}"
    if month_restricted and not dom_restricted and not dow_restricted:
        return f"in {describe_month(month)}"

    # General fallback: state whichever fields are restricted. Note that in
    # real cron, a restricted day_of_month combined with a restricted
    # day_of_week is an OR ("either the 1st, or any Monday"), not an AND;
    # this phrasing lists both without asserting which logic applies.
    clauses = []
    if dom_restricted:
        clauses.append(f"on the {describe_day_of_month(day_of_month)}")
    if month_restricted:
        clauses.append(f"in {describe_month(month)}")
    if dow_restricted:
        clauses.append(f"on {describe_day_of_week(day_of_week)}")
    return " ".join(clauses)


# --------------------------------------------------------------------------
# Description: single-field helpers
# --------------------------------------------------------------------------

def describe_day_of_week(field: CronField) -> str:
    names_by_value = {value: DAY_NAMES[value] for value in field.values}
    return describe_named_groups(field.values, names_by_value)


def describe_month(field: CronField) -> str:
    names_by_value = {value: MONTH_NAMES[value] for value in field.values}
    return describe_named_groups(field.values, names_by_value)


def describe_day_of_month(field: CronField) -> str:
    names_by_value = {value: ordinal(value) for value in field.values}
    return describe_named_groups(field.values, names_by_value)


def describe_number_list(values: List[int]) -> str:
    return join_with_and([str(value) for value in values])


def describe_named_groups(values: List[int], names_by_value: Dict[int, str]) -> str:
    """Turn e.g. [1,2,3,4,5] into "Monday through Friday", or [1,3,5] into
    "Monday, Wednesday, and Friday", using each value's name.
    """
    phrases = []
    for start, end in group_consecutive_values(values):
        if start == end:
            phrases.append(names_by_value[start])
        else:
            phrases.append(f"{names_by_value[start]} through {names_by_value[end]}")
    return join_with_and(phrases)


# --------------------------------------------------------------------------
# Small generic helpers
# --------------------------------------------------------------------------

def is_wildcard(field: CronField) -> bool:
    """True if the field's raw text is exactly "*" (matches every value)."""
    return field.raw == "*"


def wildcard_step(field: CronField) -> Optional[int]:
    """Return N if the field's raw text is exactly "*/N", else None."""
    if field.raw.startswith("*/"):
        return int(field.raw[2:])
    return None


def single_value(field: CronField) -> Optional[int]:
    """Return the field's one value if it matches exactly one, else None."""
    if len(field.values) == 1:
        return field.values[0]
    return None


def group_consecutive_values(values: List[int]) -> List[Tuple[int, int]]:
    """Collapse a sorted list of ints into (start, end) runs, e.g.
    [1, 2, 3, 5, 7, 8] -> [(1, 3), (5, 5), (7, 8)].
    """
    runs: List[Tuple[int, int]] = []
    for value in values:
        previous_run_end = runs[-1][1] if runs else None
        if previous_run_end is not None and value == previous_run_end + 1:
            runs[-1] = (runs[-1][0], value)
        else:
            runs.append((value, value))
    return runs


def join_with_and(items: List[str]) -> str:
    """Join into an English list: "A", "A and B", or "A, B, and C"."""
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return f"{items[0]} and {items[1]}"
    return ", ".join(items[:-1]) + f", and {items[-1]}"


def ordinal(n: int) -> str:
    """1 -> "1st", 2 -> "2nd", 3 -> "3rd", 11 -> "11th", 21 -> "21st", ..."""
    if 10 <= n % 100 <= 20:
        suffix = "th"
    else:
        suffix = {1: "st", 2: "nd", 3: "rd"}.get(n % 10, "th")
    return f"{n}{suffix}"


